/* 仿qq·蓝 by点星 禁止二传 */
:root {
  --chat-header-bg: #f0f6fc; /* 顶栏底色 淡蓝调 */
  --input-area-bg: #ffffff; /* 底栏底色 */
  --chat-header-title-color: #d4af37; /* 备注标题颜色 */
}

/* 彻底隐藏顶栏原生头像 */
.header-avatar-container,
.chat-header-avatar {
  display: none !important;
  visibility: hidden !important;
}

/* 右一设置键 图标+尺寸 */
.header-btn-info {
  background: url(https://imgbed.heliar.top/i/j7aP-9-xjPhCh2nh_retouch_2026061115593993.webp) center / 16px no-repeat !important;
  width: 24px !important;
  height: 24px !important;
}
.header-btn-info svg {
  display: none !important;
}

/* 【核心修复】右二、右三：仅隐藏内部原生图标，强制保留外层按钮点击权限，提升层级避免拦截 */
 .header-btn-phone,
 .header-btn-video {
   pointer-events: auto !important;
   position: relative !important;
   z-index: 10 !important;
   width: 32px !important;
   height: 32px !important;
 }
 .header-btn-phone svg,
 .header-btn-video svg {
   display: none !important;
   visibility: hidden !important;
 }

/* 顶栏整体排布 */
.chat-header-custom {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  position: relative !important;
}

/* 主标题，保持inline-flex自适应跟随结构不变 */
.chat-header-title {
  margin-left: -10px !important; /* 负数越小，越往左 */
  position: relative !important;
  top: -7px !important; /* 备注+图标整体上移，负数越小，越往上 */
  line-height: 1.2 !important;
  display: inline-flex !important;
  align-items: center !important;
}

/* 备注文字后面跟随图标，长短自动适配 完全保留 */
.chat-header-title::after {
  content: "";
  display: inline-block !important;
  width: 49px;
  height: 49px;
  margin-left: 7px; /* 数字越大，备注标题和图标间距越大 */
  background: url(https://imgbed.heliar.top/i/QJb5n1PWnnbGFlGd_retouch_2026061114525961.webp) center/contain no-repeat;
  pointer-events: none;
}

/* 副标题上移，紧贴备注底部 */
.chat-header-custom::after {
  content: "在线-幸福放慢倍速 🐾";
  position: absolute;
  left: calc(2px + 41px); /* 41px数字越大，越往右 */
  top: calc(100% - 26px); /* 26px数字越大，越往上 */
  font-size: 11px;
  color: #000; /* 副标题文案字体颜色 */
  white-space: nowrap;
  z-index: 99;
}

/**
 * 极致缩高 + 隐滚动条/提示词 + 弱化顶部分割线 + 浅色系输入框 + 底部背景图
 * 
 * [最终修正版] By Gemini
 */

/* --- 1. 整体布局 & 弱化顶线 --- */
.input-area-custom {
  position: relative; 
  padding: 8px 12px 45px 12px !important; 
  display: block;
  min-height: auto;
  border-top: none !important; /* 彻底移除上边框 */
  box-shadow: none !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  overflow: hidden; 
}

/* --- 2. 外层输入框容器 改为淡淡蓝色底色 --- */
.input-action-bar-custom {
  position: relative; 
  z-index: 1;
  display: flex;    
  align-items: center;
  width: 100% !important;
  background: #f0f6fc !important;
  padding: 2px 10px !important;
  border-radius: 24px !important;
  border: 1px solid rgba(175, 200, 225, 0.25) !important;
}

/* --- 3. 核心输入框 textarea --- */
.input-box-custom {
  flex-grow: 1;
  background: transparent !important;
  min-height: 0 !important;
  padding: 2px 4px !important;
  line-height: 16px !important;
  max-height: 24px !important;

  /* 隐藏滚动条 全平台兼容 */
  overflow: hidden !important;
  &::-webkit-scrollbar {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
  }
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

/* 隐藏占位提示文字 */
.input-box-custom::placeholder {
  color: transparent !important;
  opacity: 0 !important;
}

/* 隐藏原生按钮容器 */
.input-action-bar-custom .input-btns-right {
  display: none;
}

/* --- 4. 底部五个按钮 (可独立调节 left / top) --- */
.input-btn-plus,
.input-btn-mic,
.input-btn-sticker,
.input-btn-ai,
.send-btn-custom,
.stop-btn-custom {
  position: absolute !important; 
  order: initial;
  z-index: 1;

  /* 基础样式，确保按钮正确显示 */
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  line-height: 1 !important;

  /* 默认使用 transform 居中，如需微调可以覆盖 */
  transform: translateX(-50%);

  /* ===== 新增：隐藏原生图标，但保留按钮可点击 ===== */
  background: transparent !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}

/* 隐藏按钮内部的所有图标/图片/文字内容 */
.input-btn-plus img,
.input-btn-plus svg,
.input-btn-plus i,
.input-btn-plus span,
.input-btn-mic img,
.input-btn-mic svg,
.input-btn-mic i,
.input-btn-mic span,
.input-btn-sticker img,
.input-btn-sticker svg,
.input-btn-sticker i,
.input-btn-sticker span,
.input-btn-ai img,
.input-btn-ai svg,
.input-btn-ai i,
.input-btn-ai span,
.send-btn-custom img,
.send-btn-custom svg,
.send-btn-custom i,
.send-btn-custom span,
.stop-btn-custom img,
.stop-btn-custom svg,
.stop-btn-custom i,
.stop-btn-custom span {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}

/* 可选：如果您想让按钮本身完全透明但保留点击区域，可以添加这一行 */
.input-btn-plus,
.input-btn-mic,
.input-btn-sticker,
.input-btn-ai,
.send-btn-custom,
.stop-btn-custom {
  color: transparent !important;
  font-size: 0 !important;
}

/* 
 * ============================================
 * 五个按钮的独立位置调节 (您的原始数值，完全未动)
 * ============================================
 */

/* 按钮1: 加号 */
.input-btn-plus { 
  left: 7%; /* 数字越大，越往右 */
  top: auto;
  bottom: 4px; /* 数字越小，越往下 */
}

/* 按钮2: 麦克风 */
.input-btn-mic { 
  left: 25%;
  bottom: -40px; /* 负数越小，越往下 */
}

/* 按钮3: 表情/贴纸 */
.input-btn-sticker { 
  left: 42%;
  bottom: -40px;
}

/* 按钮4: AI */
.input-btn-ai { 
  left: 58%;
  bottom: -40px;
}

/* 按钮5: 发送/停止 */
.send-btn-custom,
.stop-btn-custom { 
  left: 90%;
  bottom: -40px;
}

/* --- 5. 底部背景图层（淡蓝色）--- */
.input-area-custom::after {
  content: ""; 
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 45px; 
  background-image: url('https://imgbed.heliar.top/i/_8g7K7o6XML1H24l_retouch_2026061212131718.webp');
  background-repeat: no-repeat;
  background-position: center;
  background-size: 80% auto;
  filter: grayscale(100%) brightness(1.2) sepia(1) hue-rotate(180deg) saturate(1.2) !important;
  opacity: 0.55 !important;
  pointer-events: none !important;
}

:root {
  /* 整体气泡宽度 */
  --chat-message-max-width: 64%;

  /* ---------- 我方气泡 ---------- */
  --bubble-me-bg: #ffffff; /* 我方底色纯白 */
  --bubble-me-color: #222222;
  --bubble-me-padding: 5px 9px; /* 文字与边框间距 */
  --bubble-me-radius: 30px;
  --bubble-me-radius-first: 30px 30px 6px 30px;
  --bubble-me-radius-mid: 30px 6px 6px 30px;
  --bubble-me-radius-last: 30px 6px 30px 30px;
  --bubble-me-border: 1px solid #d1e0ee;
  --bubble-me-shadow: none;

  /* ---------- 对方气泡 淡蓝色 ---------- */
  --bubble-them-bg: #f0f6fc; /* 对方淡蓝底色 */
  --bubble-them-color: #222222;
  --bubble-them-padding: 5px 9px; /* 文字与边框间距 */
  --bubble-them-radius: 30px;
  --bubble-them-radius-first: 30px 30px 6px 30px;
  --bubble-them-radius-mid: 6px 30px 30px 6px;
  --bubble-them-radius-last: 6px 30px 30px 30px;
  --bubble-them-border: 1px solid #bcd0e2;
  --bubble-them-shadow: none;

  /* ========== 语音波形配色（原生单层，无额外边框/嵌套） ========== */
  --voice-me-color: #222222;
  --voice-me-bar-active: #d1e0ee;
  --voice-me-bar-inactive: #ffffff;

  --voice-them-color: #222222;
  --voice-them-bar-active: #bcd0e2;
  --voice-them-bar-inactive: #f0f6fc;

  /* ========== 转账卡片 严格匹配对应气泡样式 ========== */
  --transfer-me-card-bg: #ffffff;
  --transfer-me-card-border: 1px solid #d1e0ee;
  --transfer-me-card-radius: 30px;

  --transfer-them-card-bg: #f0f6fc;
  --transfer-them-card-border: 1px solid #bcd0e2;
  --transfer-them-card-radius: 30px;
}

/* 文本气泡基础样式 + 定位支持 */
.bubble-me-custom {
  background: var(--bubble-me-bg) !important;
  border: var(--bubble-me-border) !important;
  position: relative !important;
  overflow: visible !important;
}
.bubble-them-custom {
  background: var(--bubble-them-bg) !important;
  border: var(--bubble-them-border) !important;
  position: relative !important;
  overflow: visible !important;
}

/* 我方左上角星星 - 淡蓝色调 */
.bubble-me-custom::before {
  content: "★";
  position: absolute;
  top: -6px;
  left: 1px;
  font-size: 14px;
  color: #a9bed4;
  transform: rotate(-35deg) !important;
  transform-origin: center center !important;
  pointer-events: none;
  z-index: 2;
}

/* 对方右上角星星 - 淡蓝色调 */
.bubble-them-custom::before {
  content: "★";
  position: absolute;
  top: -6px;
  right: 1px;
  font-size: 14px;
  color: #a9bed4;
  transform: rotate(35deg) !important;
  transform-origin: center center !important;
  pointer-events: none;
  z-index: 2;
}

/* 转账卡片 强化匹配气泡样式 */
.msg-me .msg-transfer-card {
  background: var(--transfer-me-card-bg) !important;
  border: var(--transfer-me-card-border) !important;
  border-radius: var(--transfer-me-card-radius) !important;
}
.msg-them .msg-transfer-card {
  background: var(--transfer-them-card-bg) !important;
  border: var(--transfer-them-card-border) !important;
  border-radius: var(--transfer-them-card-radius) !important;
}

/* 只命中包含图片/表情的气泡，文字/语音气泡完好无损 */
.bubble-me-custom:has(img),
.bubble-them-custom:has(img),
.bubble-me-custom:has([class*="sticker"]),
.bubble-them-custom:has([class*="sticker"]),
.bubble-me-custom:has([class*="emoji"]),
.bubble-them-custom:has([class*="emoji"]) {
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
}

/* 清除这些气泡上的星星 */
.bubble-me-custom:has(img)::before,
.bubble-them-custom:has(img)::before,
.bubble-me-custom:has(img)::after,
.bubble-them-custom:has(img)::after,
.bubble-me-custom:has([class*="sticker"])::before,
.bubble-them-custom:has([class*="sticker"])::before,
.bubble-me-custom:has([class*="emoji"])::before,
.bubble-them-custom:has([class*="emoji"])::before {
  content: none !important;
  display: none !important;
}

/* 缩小表情包和图片 */
.bubble-me-custom img,
.bubble-them-custom img,
.bubble-me-custom [class*="sticker"],
.bubble-them-custom [class*="sticker"],
.bubble-me-custom [class*="emoji"],
.bubble-them-custom [class*="emoji"] {
  max-width: 110px !important;
  max-height: 110px !important;
  width: auto !important;
  height: auto !important;
}

/* ==========================================
   翻译展开（打开自动展开按钮）
   ========================================== */

.msg-translation-wrapper {
  display: block !important;
  max-height: none !important;
  opacity: 1 !important;
  visibility: visible !important;
}

.msg-translation-btn {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  overflow: hidden !important;
  opacity: 0 !important;
  visibility: hidden !important;
}

.msg-translation-content {
  display: block !important;
  margin-top: 2px !important;
  padding: 0 !important;
  border-top: none !important;
  font-size: 13px !important;
  line-height: 1.4 !important;
  opacity: 0.85 !important;
  max-height: none !important;
  overflow: visible !important;
}

.msg-me .msg-translation-content {
  color: #1a1a1a !important;
  background: transparent !important;
}

.msg-them .msg-translation-content {
  color: #1a1a1a !important;
  background: transparent !important;
}

.msg-me .msg-translation-wrapper,
.msg-them .msg-translation-wrapper {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
}

