  --bubble-them-border: 1px solid rgba(0, 0, 0, 0.08) !important;

  --bubble-them-shadow: none !important;
  --bubble-me-shadow: none !important;

  /* 强制从根节点把时间戳文字改为白色 */
  --timestamp-color: #ffffff !important;
  --date-divider-color: #ffffff !important;
}

/* =======================================
   🔺 2️⃣ 气泡小三角 (无缝融合 + 柔和尖尖版)
   ======================================= */
.bubble-me-custom, .bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
}

/* 我方右侧小三角 */
.bubble-me-custom::after {
  content: "";
  position: absolute;
  top: 14px;
  right: -4px; 
  width: 8px;
  height: 8px;
  background-color: var(--bubble-me-bg);

  /* 只留露在外侧的这两条边框，颜色跟随极淡边框 */
  border-top: 1px solid rgba(0, 0, 0, 0.05);
  border-right: 1px solid rgba(0, 0, 0, 0.05);

  /* 砍掉藏在内部的边框，防止颜色重叠变深 */
  border-bottom: none !important;
  border-left: none !important;

  transform: rotate(45deg);

  /* 让尖尖稍微有一点圆润，更贴近原生质感 */
  border-top-right-radius: 1.5px;

  /* 提高层级，用背景色死死盖住气泡本体的右边框 */
  z-index: 2 !important;
}

/* 对方左侧小三角 */
.bubble-them-custom::after {
  content: "";
  position: absolute;
  top: 14px;
  left: -4px; 
  width: 8px;
  height: 8px;
  background-color: var(--bubble-them-bg);

  /* 只留露在外侧的这两条边框 */
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  border-left: 1px solid rgba(0, 0, 0, 0.08);

  /* 砍掉内部的边框 */
  border-top: none !important;
  border-right: none !important;

  transform: rotate(45deg);
  border-bottom-left-radius: 1.5px;
  z-index: 2 !important;
}

