   💸 8️⃣ 微信写实版转账卡片 (修复多行文字 + 彻底去边框版)
   ======================================= */

:root {
  /* 🔪 彻底抽空原生黑点底座和各种状态的红绿警示灯 */
  --transfer-icon-bg: transparent !important;
  --transfer-me-icon-bg: transparent !important;
  --transfer-them-icon-bg: transparent !important;
  --transfer-success-icon-bg: transparent !important;
  --transfer-rejected-icon-bg: transparent !important;
  --transfer-expired-icon-bg: transparent !important;

  /* 🔪 彻底抽空原生系统自带的卡片细边框 */
  --transfer-card-border: none !important;
  --transfer-me-card-border: none !important;
  --transfer-them-card-border: none !important;
  --transfer-success-card-border: none !important;
  --transfer-rejected-card-border: none !important;
  --transfer-expired-card-border: none !important;
}

/* 默认状态：亮橙色 */
.chat-detail-screen .msg-transfer-card {
  width: 230px !important;
  height: 90px !important;
  background-color: #FF9709 !important; 
  border-radius: 4px !important;        
  position: relative !important;
  padding: 0 !important; 
  overflow: hidden !important; 
  display: block !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}

/* 已收款状态：浅橙色 */
.chat-detail-screen .msg-transfer-card.msg-transfer-success {
  background-color: #F7D0A2 !important; 
}

/* 拒收 / 过期状态：浅灰色 */
.chat-detail-screen .msg-transfer-card.msg-transfer-rejected,
.chat-detail-screen .msg-transfer-card.msg-transfer-expired-card {
  background-color: #D4D4D4 !important; 
}

/* 2. 画出底部的那块白色区域 */
.chat-detail-screen .msg-transfer-card::before {
  content: "";
  position: absolute;
  bottom: 0; left: 0; width: 100%; height: 22px;
  background-color: #ffffff;
  border: none !important;
  z-index: 1;
}

/* 3. 隐藏系统默认图标和分割线 */
.chat-detail-screen .msg-transfer-card svg,
.chat-detail-screen .msg-transfer-divider {
  display: none !important;
}

/* 4. 在左侧贴上您指定的转账贴图 */
.chat-detail-screen .msg-transfer-card::after {
  content: "";
  position: absolute;
  top: 14px; left: 14px; width: 40px; height: 40px;
  background-image: url('https://i.imgant.com/v2/bIZjqeh.png');
  background-size: 100% 100%; background-repeat: no-repeat; z-index: 2;
}

/* 5. 调整金额文字 (上面第一行) */
/* 外层容器：负责定位、强制横排、绝不换行 */
.chat-detail-screen .msg-transfer-amount {
  position: absolute !important;
  top: 15px !important;
  left: 64px !important;      
  z-index: 2 !important;
  display: flex !important;           
  flex-direction: row !important;
  align-items: baseline !important;   
  white-space: nowrap !important;     
}
.chat-detail-screen .msg-transfer-amount,
.chat-detail-screen .msg-transfer-amount * {
  color: #ffffff !important;  
  -webkit-text-fill-color: #ffffff !important; 
  font-size: 16px !important;
  font-weight: 500 !important;
  line-height: 1 !important;
  background: transparent !important; 
}

/* 6. 调整说明文字 “转账给xxx” (下面第二行) */
/* 外层容器：定位、定宽、允许多行 */
.chat-detail-screen .msg-transfer-label {
  position: absolute !important; 
  top: 38px !important;            /* 往上提2px，给双行文字留足空间 */
  left: 64px !important;
  width: 155px !important;         /* 强制宽度，刚好填满右侧剩余空间 */
  z-index: 2 !important; 

  /* 多行截断魔法：最多两行，超过变省略号 */
  display: -webkit-box !important; 
  -webkit-box-orient: vertical !important;
  -webkit-line-clamp: 2 !important; 
  white-space: normal !important;  /* 允许换行！ */
  overflow: hidden !important;
}
/* 内层文字：染白 + 允许换行 */
.chat-detail-screen .msg-transfer-label,
.chat-detail-screen .msg-transfer-label * {
  color: #ffffff !important; 
  -webkit-text-fill-color: #ffffff !important; 
  font-size: 12px !important; 
  line-height: 1.2 !important;      /* 稍微增加行高，防止多行字挤在一起 */
  background: transparent !important; 
  font-weight: 300 !important;      /* 细体字 */
  white-space: normal !important;   /* 强制内部元素也允许换行！ */
}

/* 7. 底部“微信转账”文字 */
.chat-detail-screen .msg-transfer-status-text {
  position: absolute !important; bottom: 4px !important; left: 14px !important; font-size: 0 !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important; background: transparent !important;
}
.chat-detail-screen .msg-transfer-status-text::after {
  content: "微信转账"; font-size: 11px !important; color: #b2b2b2 !important; -webkit-text-fill-color: #b2b2b2 !important; 
}
.chat-detail-screen .msg-transfer-subtitle { display: none !important; }

/* =======================================
   🖼️ 9️⃣ 文字图片长图 (.msg-sim-card) 正方形盲盒美化
   ======================================= */
.chat-detail-screen .msg-sim-card {
  width: 150px !important;
  height: 150px !important;
  position: relative !important;
  overflow: hidden !important;
  border-radius: 8px !important;
  cursor: pointer !important;
  background-color: #ffffff !important; /* 给内部文字一个底色 */
}

/* 封面贴图，盖在最上面 */
.chat-detail-screen .msg-sim-card::after {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image: url('https://i.imgant.com/v2/1Svz68X.jpeg');
  background-size: cover;
  background-position: center;
  z-index: 10;
  transition: opacity 0.2s ease-in-out;
}

/* 👇 点击长按时，隐藏封面露出里面的文字 */
.chat-detail-screen .msg-sim-card:active::after {
  opacity: 0 !important;
  pointer-events: none !important;
}

/* =======================================
   🔧 🔟 修复顶栏功能键隐藏后仍可点击的问题
   ======================================= */
/* 单独加这段给您的顶栏擦屁股：全透明，但保持指针响应 */
.chat-detail-screen .header-btn-phone,
.chat-detail-screen .header-btn-video {
  opacity: 0 !important;
  pointer-events: auto !important; 
  display: block !important;
}

/* =======================================
   🧠 11. 思维链美化 (紧凑黑透毛玻璃 + 加粗 Online)
   ======================================= */
:root {
