/* =========================================
   古早微信风格顶栏 (Classic WeChat Header)
   ========================================= */

:root {
    /* 1. 顶栏底色 232323，关闭系统模糊 */
    --chat-header-bg: #232323;
    --chat-header-blur: 0px;
    --chat-header-border: transparent;
    --chat-header-title-color: #ffffff;
    --chat-header-title-size: 17px;

    /* 🔻 顶栏固定高度调整（无论内部贴图多大，顶栏都不会被撑开） */
    --chat-header-height: 100px; 

    /* 2. 替换返回键贴图 */
    --back-btn-icon: url('https://i.imgant.com/v2/rwPViEA.png');

    /* 🔻 返回键：大小与位置调整 */
    --btn-back-scale: 1.2;           
    --btn-back-translate-x: 0px;     
    --btn-back-translate-y: 0px;     

    /* 🔻 视频键：大小与位置调整 */
    --btn-video-scale: 1.1;
    --btn-video-translate-x: 0px;
    --btn-video-translate-y: 3px;
    /* 🌟 调好位置后，把下面这行的 1 改成 0，就能【透明且可点击】了！ */
    --btn-video-opacity: 0;

    /* 🔻 通话键：大小与位置调整 */
    --btn-phone-scale: 1.1;
    --btn-phone-translate-x: 0px;
    --btn-phone-translate-y: 3px;
    /* 🌟 调好位置后，把下面这行的 1 改成 0，就能【透明且可点击】了！ */
    --btn-phone-opacity: 0;

    /* =========================================
       系统真实未读徽章接管 (毛玻璃 99+ 与 红点)
       ========================================= */

    /* 数字徽章 (系统有未读时自动读取这里的样式) */
    --chat-header-unread-num-display: flex;
    --chat-header-unread-num-bg: rgba(255, 255, 255, 0.75); /* 白底半透明 */
    --chat-header-unread-num-color: #000000;
    --chat-header-unread-num-size: 10px;
    --chat-header-unread-num-weight: 700;
    --chat-header-unread-num-padding: 2px 6px;
    --chat-header-unread-num-radius: 12px;
    --chat-header-unread-num-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
    /* 🔻 调整【数字徽章】的位置（相对返回键） */
    --chat-header-unread-num-top: 12px;
    --chat-header-unread-num-left: 28px;

    /* 小红点 (放在数字右上角) */
    --chat-header-unread-bg: #ff3b30;
    --chat-header-unread-size: 6px;
    --chat-header-unread-shadow: 0 1px 2px rgba(255, 59, 48, 0.5);
    /* 🔻 调整【红点】的位置（如果动了数字位置，红点也要跟着微调） */
    --chat-header-unread-top: 10px;
    --chat-header-unread-left: 48px;
    --chat-header-unread-z: 3;
}

/* 强制锁死顶栏高度，不允许内部元素外溢撑开它 */
.chat-header-custom {
    height: var(--chat-header-height) !important;
    min-height: var(--chat-header-height) !important;
    max-height: var(--chat-header-height) !important;
}

/* 为系统的数字徽章加上真实的毛玻璃滤镜 */
.nuo-chat-header-unread-num {
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
}

